local VacuumCasterMaker = {}
local PRODUCTS = {
    iron_vacuumcaster = { name = "Železni vakuumski ulitev", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vakuumski ulitev za livarje." },
    bronze_vacuumcaster = { name = "Bronast vakuumski ulitev", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vakuumski ulitev za livarje." },
    silver_vacuumcaster = { name = "Srebrn vakuumski ulitev", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vakuumski ulitev za livarje." },
    gilded_vacuumcaster = { name = "Pozlačen vakuumski ulitev", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vakuumski ulitev za livarje." },
    jewel_set_vacuumcaster = { name = "Draguljast vakuumski ulitev", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vakuumski ulitev za livarje." },
    royal_sovereign_vacuumcaster = { name = "Kraljevski suveren vakuumski ulitev", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vakuumski ulitev z biseri za krono." },
}
local BUILDINGS = {
    vacuumcaster_workshop = { name = "Vacuumcaster delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    vacuumcaster_house = { name = "Vacuumcaster hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_vacuumcaster_atelier = { name = "Mojstrski vacuumcaster atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_vacuumcaster_palace = { name = "Suverena vacuumcaster palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
VacuumCasterMaker.ironStock = 16; VacuumCasterMaker.bronzeStock = 14; VacuumCasterMaker.woodStock = 10; VacuumCasterMaker.leatherStock = 10; VacuumCasterMaker.silverStock = 8; VacuumCasterMaker.goldStock = 6; VacuumCasterMaker.jewelStock = 4; VacuumCasterMaker.pearlStock = 4
VacuumCasterMaker.productStock = {}; VacuumCasterMaker.buildings = {}; VacuumCasterMaker.maker = nil; VacuumCasterMaker.activeMaking = {}; VacuumCasterMaker.totalProducts = 0; VacuumCasterMaker.dayTimer = 0
function VacuumCasterMaker.init() VacuumCasterMaker.ironStock=16; VacuumCasterMaker.bronzeStock=14; VacuumCasterMaker.woodStock=10; VacuumCasterMaker.leatherStock=10; VacuumCasterMaker.silverStock=8; VacuumCasterMaker.goldStock=6; VacuumCasterMaker.jewelStock=4; VacuumCasterMaker.pearlStock=4; VacuumCasterMaker.productStock={}; VacuumCasterMaker.buildings={}; VacuumCasterMaker.maker=nil; VacuumCasterMaker.activeMaking={}; VacuumCasterMaker.totalProducts=0; VacuumCasterMaker.dayTimer=0; print("[VacuumCasterMaker] Royal Vacuum Caster Maker System initialized (6 products, 4 buildings)") end
function VacuumCasterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=595+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; VacuumCasterMaker.maker={name=n or ("Vakuumec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vakuumec najet: %s (spretnost: %d)",VacuumCasterMaker.maker.name,s),"success") end; return true end
function VacuumCasterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function VacuumCasterMaker.build(id) local ok,e=VacuumCasterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(VacuumCasterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function VacuumCasterMaker.getQualityBonus() local b=0; for _,bd in ipairs(VacuumCasterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function VacuumCasterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and VacuumCasterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and VacuumCasterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and VacuumCasterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and VacuumCasterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and VacuumCasterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and VacuumCasterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and VacuumCasterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and VacuumCasterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #VacuumCasterMaker.buildings==0 then return false,"Potrebna vakuumna delavnica" end; if not VacuumCasterMaker.maker then return false,"Potreben vakuumec" end; return true end
function VacuumCasterMaker.make(pt,qty) qty=qty or 1; local ok,e=VacuumCasterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then VacuumCasterMaker.ironStock=VacuumCasterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then VacuumCasterMaker.bronzeStock=VacuumCasterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then VacuumCasterMaker.woodStock=VacuumCasterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then VacuumCasterMaker.leatherStock=VacuumCasterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then VacuumCasterMaker.silverStock=VacuumCasterMaker.silverStock-d.silverCost*qty end; if d.goldCost then VacuumCasterMaker.goldStock=VacuumCasterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then VacuumCasterMaker.jewelStock=VacuumCasterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then VacuumCasterMaker.pearlStock=VacuumCasterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if VacuumCasterMaker.maker then t=math.max(1,t-math.floor(VacuumCasterMaker.maker.skill/13)) end; table.insert(VacuumCasterMaker.activeMaking,{id="${MAKER_LOWER}_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function VacuumCasterMaker.completeMaking(m) local q=1.0+(VacuumCasterMaker.getQualityBonus()/100); if VacuumCasterMaker.maker then q=q+(VacuumCasterMaker.maker.skill/140) end; q=math.min(2.5,q); VacuumCasterMaker.productStock[m.productType]=(VacuumCasterMaker.productStock[m.productType] or 0)+m.quantity; VacuumCasterMaker.totalProducts=VacuumCasterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if VacuumCasterMaker.maker then VacuumCasterMaker.maker.itemsMade=VacuumCasterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then VacuumCasterMaker.maker.skill=math.min(100,VacuumCasterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vakuum izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"${MAKER_LOWER}.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function VacuumCasterMaker.update(dt) if not _G.state then return end; VacuumCasterMaker.dayTimer=VacuumCasterMaker.dayTimer+dt; if VacuumCasterMaker.dayTimer>=30 then VacuumCasterMaker.dayTimer=0; for i=#VacuumCasterMaker.activeMaking,1,-1 do local m=VacuumCasterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then VacuumCasterMaker.completeMaking(m); table.remove(VacuumCasterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(VacuumCasterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if VacuumCasterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function VacuumCasterMaker.getStats() return {ironStock=VacuumCasterMaker.ironStock,bronzeStock=VacuumCasterMaker.bronzeStock,woodStock=VacuumCasterMaker.woodStock,leatherStock=VacuumCasterMaker.leatherStock,silverStock=VacuumCasterMaker.silverStock,goldStock=VacuumCasterMaker.goldStock,jewelStock=VacuumCasterMaker.jewelStock,pearlStock=VacuumCasterMaker.pearlStock,productStock=VacuumCasterMaker.productStock,numBuildings=#VacuumCasterMaker.buildings,hasMaker=VacuumCasterMaker.maker~=nil,makerName=VacuumCasterMaker.maker and VacuumCasterMaker.maker.name or "—",makerSkill=VacuumCasterMaker.maker and VacuumCasterMaker.maker.skill or 0,activeMaking=#VacuumCasterMaker.activeMaking,totalProducts=VacuumCasterMaker.totalProducts} end
return VacuumCasterMaker
